sys_script_include.script:
var ApplyExcelData = Class.create();
ApplyExcelData.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getData: function() {
      // gs.addErrorMessage('invoke getData in  ApplyData');
        var mrvsArray = [];
        var sysId = this.getParameter('sysparm_attachment_sysid');
        var imp = new sn_impex.GlideExcelParser();
        var attachment = new GlideSysAttachment();
        var attachmentStream = attachment.getContentStream(sysId);
        imp.parse(attachmentStream);
        var headers = imp.getColumnHeaders();

        while (imp.next()) {
            var row = imp.getRow();

            mrvsArray.push({
                'machine': row['Machine'],
                'storage': row['Storage'],
                'service': row['Service'],
                'note': row['Note'],

            });
			//gs.addErrorMessage('Machine ' + row['Machine']);
        }

        return JSON.stringify(mrvsArray);

    },
    type: 'ApplyExcelData'
});
